        throw ApiException.unprocessable("航段 " + legId + " 为普通航段，不支持换舱");
    }
    if (!LEG_OPEN.equals(leg.status())) {
        throw ApiException.unprocessable("航段状态为 " + leg.status() + "，封舱后禁止换舱");
    }
    List<BagCompartment> moves = request.moves();
