    for (BagCompartment move : moves) {
        if (moveMap.put(move.bagTag(), move.compartment()) != null) {
            throw ApiException.unprocessable("批量换舱的 bagTag 不得重复: " + move.bagTag());
        }
    }
    List<BalanceItem> current = liveBalanceItems(legId);
